const KOK = fileURLToPath(new URL("..", import.meta.url));
const OLC = readFileSync(join(KOK, "tools/olc-maket.js"), "utf8");
const puppeteer = createRequire("/opt/olcum/")("puppeteer-core");
/* gerçek dosya yükleme (2026-09-28): ölçüm kipi (MAKET_ORNEK) kapatılıp dosya penceresine gerçek bir PDF verilir; yüklenen dosyanın kendisinin
   göründüğü, sayfa yenilenince kaldığı, değiştirilip silindiği denenir (reisim: "yükelenilen şeyler düzenlenebilir silinebilir olmalı") */
const GERCEK = (tetik, ad) => ["js", `window.MAKET_ORNEK = false; document.querySelector(${JSON.stringify(tetik)}).click(); var g = document.querySelector("input[data-mk-dosya]"); var dt = new DataTransfer(); dt.items.add(new File(["%PDF-1.4 deneme"], ${JSON.stringify(ad)}, { type: "application/pdf" })); g.files = dt.files; g.dispatchEvent(new Event("change")); window.MAKET_ORNEK = true;`];
const YENILE = ["js", "setTimeout(function () { location.reload(); }, 400)"];

